  /// Returns the appointed spiritual verse for the day of the year (1 to 366).
  static CuratedDailyVerse getVerseForDay(int dayOfYear) {
    if (dayOfYear < 1) return verses.first;
    if (dayOfYear > verses.length) return verses.last;
    return verses[dayOfYear - 1];
  }
}
